async function loadGuests(){setHead('Customers','Save delivery details for faster repeat orders.');$('#guests').innerHTML=`<div class="columns"><form class="panel form" onsubmit="event.preventDefault();addGuest()"><h2>Add customer</h2><label>Name<input id="guest-name" required></label><label>Phone number<input id="guest-phone" type="tel" required placeholder="03XX XXXXXXX"></label><label>Email (optional)<input id="guest-email" type="email"></label><label>Delivery address<input id="guest-address" required></label><button class="primary">ADD / UPDATE CUSTOMER</button><p class="muted">An existing phone number updates that customer instead of creating a duplicate.</p></form><div><h2>Customer directory</h2><input id="guest-search" placeholder="Search name, phone or email..."><div id="guest-list" class="list"></div></div></div>`;$('#guest-search').oninput=refreshGuests;await refreshGuests()}
