async function loadManagement(){setHead('Owner control center','Manage the menu, user access, and POS settings.');const c=await api('/api/management/categories');$('#management').innerHTML=`<div class="toolbar tabs"><button onclick="adminTab('menu')">Menu & Deals</button><button onclick="adminTab('users')">Users & Roles</button><button onclick="adminTab('system')">System</button></div><div id="admin-menu" class="admin-pane columns"><form class="panel form" onsubmit="event.preventDefault();saveProduct(false)"><label>Category<select id="product-category">${c.filter(c=>c.name!=='Deals').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Name<input id="product-name" required></label><label>Description<input id="product-description"></label><label>Price<input id="product-price" type="number" min="0" step=".01" required></label><button class="primary">ADD MENU ITEM</button></form><div><h2>Current menu</h2><div id="product-list" class="list"></div><div class="toolbar"><button class="gold" onclick="saveProduct(true)">SAVE EDITS</button><button class="deny" onclick="deactivateProduct()">DEACTIVATE</button></div></div></div><div id="admin-users" class="admin-pane columns hidden"><form class="panel form" onsubmit="event.preventDefault();saveUser()"><h2>User credentials</h2><label>Username<input id="new-user" required></label><label>Role<select id="new-role"><option>cashier</option><option>owner</option></select></label><label>Password<input id="new-pass" type="password" required autocomplete="new-password"></label><button class="primary">CREATE / RESET USER</button></form><div><h2>Current users</h2><div id="user-list" class="list"></div></div></div><div id="admin-system" class="admin-pane hidden panel"><h2>System controls</h2><p>Download a complete database snapshot from this server.</p><a class="button" href="/api/management/backup">CREATE DATABASE BACKUP</a><p class="muted">Portable JSON backup includes all tables. Keep it private; restoration requires a database administrator.</p></div>`;await refreshManagement()}
